                .iter()
                .map(|source| source.declaration.entries.len())
                .sum::<usize>(),
            before_count + 3
        );
        let known_gbp_for_first_member =
            |declarations: &[crate::domain::models::entity_details::FunderDeclaration]| {
                declarations
