                    .filter_map(|entry| entry.amount.as_ref())
                    .sum::<BigDecimal>()
            };
        assert_eq!(
            known_gbp_for_first_member(&funding.declarations),
            known_gbp_for_first_member(&before.declarations) + BigDecimal::from(24)
